/**
 * Adornos vectoriales del sistema decorativo (trazados de los recursos de
 * Figma). Son puramente decorativos: aria-hidden y color por currentColor,
 * así el tono lo define un token desde quien los usa.
 */
type OrnamentProps = SVGProps<SVGSVGElement>;

