/**
 * Guirnalda de banderines (recurso de Figma, vectorizado) repetida a lo ancho.
 * Se coloca pegada al borde superior de un bloque; el color sale de los tokens
 * (accent, surface, gold). Alto fijo de 37 px: una repetición mide 265 px.
 */
export function BuntingEdge({ className }: { className?: string }) {
  const id = useId();
  return (
    <svg
      aria-hidden="true"
      focusable="false"
      width="100%"
      height="37"
      className={className}
    >
      <defs>
        <pattern id={id} width="265" height="37" patternUnits="userSpaceOnUse">
          <path
            d="M0 .5C70 12 190 12 265 .5"
            fill="none"
            strokeWidth="1"
            strokeDasharray="3 2.5"
            className="stroke-accent-strong/40"
          />
          <path className="fill-accent" d="M8.9 0.9L19.6 25.0L30.5 3.3Z" />
          <path className="fill-surface" d="M46.6 28.0L57.3 6.7L36.3 4.6Z" />
          <path className="fill-gold" d="M73.7 31.5L83.8 9.5L62.7 6.9Z" />
          <path className="fill-accent" d="M111.1 11.0L89.8 11.0L100.4 32.5Z" />
          <path
            className="fill-surface"
            d="M126.3 33.6L137.1 12.0L116.2 12.0Z"
          />
          <path className="fill-gold" d="M162.7 11.0L141.8 11.0L152.5 33.6Z" />
          <path className="fill-accent" d="M179.2 31.9L190.2 7.0L168.8 9.1Z" />
          <path className="fill-surface" d="M217.0 4.1L196.1 6.5L206.3 28.4Z" />
          <path className="fill-gold" d="M244.0 1.0L222.4 3.4L233.3 25.1Z" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill={`url(#${id})`} />
    </svg>
  );
}
